INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (100, 'RED', 'NYC');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (1, 999, 1, '2023-01-01', 100);

